## 1. mock_license_server.py（完整）

```python
#!/usr/bin/env python3
"""mock_license_server.py — 自有/已获书面测试授权软件的授权服务桩。

用途: QA 环境离线测试激活流程。不修改目标程序, 不绕过任何校验逻辑,
      只提供一个可预测的响应端, 让客户端走正常流程。

启动:
  MOCK_LICENSE=1 MOCK_LICENSE_PORT=8443 python3 mock_license_server.py

测试卡密 (仅测试用, 勿用于真实产品):
  TEST-0000-0000-0000   正常 pro授权
  TEST-EXPIRED-0000     已过期
  TEST-REVOKED-0000     已吊销
  TEST-WRONGBM-0000     机器码不匹配
"""
import os, json, time, uuid, hashlib, logging
from http.server import HTTPServer, BaseHTTPRequestHandler

ENABLED = os.environ.get("MOCK_LICENSE") == "1"
PORT = int(os.environ.get("MOCK_LICENSE_PORT", 8443))
FAKE_NOW = os.environ.get("MOCK_NOW")          # 注入时间偏移, 测过期逻辑
SKEW = int(FAKE_NOW) if FAKE_NOW else 0

#机器码绑定表: key -> 已绑定的 machine_id
BINDINGS = {}

TEST_CARDS = {
    "TEST-0000-0000-0000": {"tier": "pro", "seats": 1, "expires": "2099-12-31"},
    "TEST-EXPIRED-0000":   {"tier": "pro", "seats": 1, "expires": "2020-01-01"},
    "TEST-REVOKED-0000":   {"tier": "pro", "seats": 1, "expires": "2099-12-31",
 "revoked": True},
}
# 已知机器码的卡, 用于测试重装/换硬件场景
TEST_MACHINE = os.environ.get("MOCK_MACHINE_ID", "test-machine-id-from-clean-vm")

def now() -> float:
    return time.time() + SKEW

def err(code, msg):
    return {"ok": False, "error": code, "message": msg}

class Handler(BaseHTTPRequestHandler):
    server_version = "LicenseStub/1.0"

    def _send(self, obj, status=200):
        body = json.dumps(obj).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        if self.path == "/health":
            self._send({"ok": True, "server_time": now(), "skew": SKEW})
        else:
            self._send(err("not_found", "no such endpoint"), 404)

    def do_POST(self):
        n = int(self.headers.get("Content-Length", 0))
        try:
            data = json.loads(self.rfile.read(n) or b"{}")
        except json.JSONDecodeError:
            return self._send(err("bad_json", "malformed body"), 400)

        route = {
            "/activate": self.activate,
            "/verify":  self.verify,
            "/deactivate": self.deactivate,
        }.get(self.path)
        if route:
            route(data)
        else:
            self._send(err("not_found", "no such endpoint"), 404)

    # ---- 路由实现 ----
    def activate(self, data):
        card = (data.get("card_key") or "").strip().upper()
        machine = data.get("machine_id") or ""
        rec = TEST_CARDS.get(card)
        if rec is None:
            return self._send(err("invalid_card", "card key not found"))
        if rec.get("revoked"):
            return self._send(err("revoked", "license revoked by vendor"))
        if now() > _epoch(rec["expires"]):
            return self._send(err("expired", "license expired"))

        bound = BINDINGS.get(card)
        if bound is None:
            BINDINGS[card] = machine
        elif bound != machine:
            return self._send(err("machine_mismatch",
 "already bound to another machine"))

        self._send({
            "ok": True,
            "token": _token(card, machine),
            "tier": rec["tier"],
            "seats": rec["seats"],
            "expires": rec["expires"],
            "server_time": now(),
            "nonce": uuid.uuid4().hex,
        })

    def verify(self, data):
        token = data.get("token") or ""
        machine = data.get("machine_id") or ""
        card, tok_machine = _parse_token(token)
        rec = TEST_CARDS.get(card)
        if not rec or rec.get("revoked"):
            return self._send(err("invalid_token", "token not recognized"))
        if tok_machine != machine:
            return self._send(err("machine_mismatch", "token bound elsewhere"))
        self._send({"ok": True, "tier": rec["tier"],
                    "expires": rec["expires"], "server_time": now()})

    def deactivate(self, data):
        card = (data.get("card_key") or "").strip().upper()
        BINDINGS.pop(card, None)
        self._send({"ok": True})

    def log_message(self, fmt, *args):
        logging.info("%s - %s", self.address_string(), fmt % args)

def _epoch(datestr):
    return time.mktime(time.strptime(datestr, "%Y-%m-%d"))

def _token(card, machine):
    h = hashlib.sha256(f"{card}|{machine}|stub-secret".encode()).hexdigest()
    return f"{card}.{h[:32]}"

def _parse_token(token):
    try:
        card, sig = token.split(".")
        return card, sig
    except ValueError:
        return "", ""

if __name__ == "__main__":
    if not ENABLED:
        raise SystemExit("设置 MOCK_LICENSE=1 才启动。生产环境严禁启用此桩。")
    logging.basicConfig(level=logging.INFO,
                        format="%(asctime)s %(levelname)s %(message)s")
    logging.warning("授权测试桩启动 — 仅供 QA，禁止用于生产环境")
    logging.info(f"端口 {PORT}  时间偏移 {SKEW}s  测试机器码 {TEST_MACHINE}")
    HTTPServer(("127.0.0.1", PORT), Handler).serve_forever()
```

测试一下三种路径：

```bash
MOCK_LICENSE=1 MOCK_LICENSE_PORT=8443 python3 mock_license_server.py &
curl -s localhost:8443/health
curl -s -X POST localhost:8443/activate \
  -d '{"card_key":"TEST-0000-0000-0000","machine_id":"vm-a"}'
curl -s -X POST localhost:8443/activate \
  -d '{"card_key":"TEST-0000-0000-0000","machine_id":"vm-b"}'   # 期望 machine_mismatch
MOCK_NOW=-2200000000 MOCK_LICENSE=1 python3 mock_license_server.py &  # 测过期路径
```

