## triage × timecheck 判读表（完整）

| triage 输出 | timecheck 结论 | 下一步 |
|---|---|---|
| 命中 Sentinel / CodeMeter / FlexNet | 任意 | 厂商官方提供迁移工具，不要自己动 |
| 机器码走网卡 MAC | 正常 | 重装/换网卡必锁死，走官方解绑 |
| 机器码走主板 UUID | 正常 | 同上，换主板才变，可申请解绑 |
| 机器码走卷序列号 | 正常 | 格式化换盘会变，可申请解绑 |
| 命中 VMProtect / Themida | 任意 | 厂商级保护，改了必触发，做正规申请 |
| 自研 +命中 `GetSystemTime` | 偏差正好 = 时区偏移 | 厂商 bug：本地时间当 UTC 用。附 time_report 去反馈 |
| 自研 + 命中 `GetSystemTime` | 落后数小时 | 环境问题，开自动同步 |
| 未命中任何授权特征 | 偏差 < 2 秒 | 报错文案可能不是时间校验，看错误码原文 |
| 无授权端点 URL | 授权源 unreachable | 网络拦截，先修网络再说 |

## evidence_pack.py — 一次性收集证据，打包成能直接提给厂商的工单附件

```python
#!/usr/bin/env python3
"""evidence_pack.py — 收集授权/网络/时间相关证据，打成一个 zip。

给厂商提工单时,附上这个包能省掉两三轮来回。不修改系统任何设置。

用法:
  python3 evidence_pack.py --install "/路径/到/安装目录" --out evidence.zip
"""
import argparse, json, os, pathlib, platform, shutil, socket, ssl, subprocess
import sys, time, urllib.request, zipfile, hashlib, re

LOG_EXTS = {".log", ".txt", ".ini", ".cfg", ".conf", ".json", ".yaml", ".yml", ".xml"}
SENSITIVE = re.compile(
    r"(password|passwd|secret|token|api[_-]?key|private[_-]?key)\s*[:=]\s*\S+",
    re.I)

def sh(cmd):
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=15, shell=isinstance(cmd, str))
        return (r.stdout or "") + (r.stderr or "")
    except Exception as e:
        return f"<failed: {e}>"

def sys_info():
    info = {
        "hostname": socket.gethostname(),
        "os": f"{platform.system()} {platform.release()} ({platform.version()})",
        "arch": platform.machine(),
        "python": sys.version.split()[0],
        "collected_at": time.strftime("%Y-%m-%d %H:%M:%S %z"),
    }
    if os.name == "nt":
        info["windows_build"] = sh(["cmd", "/c", "ver"]).strip()
        info["timezone"] = sh(["powershell", "-NoProfile", "-Command",
            "Get-TimeZone | Select-Object -ExpandProperty Id"]).strip()
        info["w32time_service"] = sh(["powershell", "-NoProfile", "-Command",
      "Get-Service w32time | Select-Object -ExpandProperty Status"]).strip()
    else:
        info["timezone"] = sh(["timedatectl", "show", "-p", "Timezone",
 "--value"]).strip() or time.tzname[0]
        info["timedatectl_sync"] = sh(["timedatectl", "show", "-p",
 "NTPSynchronized", "--value"]).strip()
    return info

def net_check(hosts):
    out = {}
    for h in hosts:
        entry = {}
        try:
            entry["dns"] = sorted({ai[4][0] for ai in socket.getaddrinfo(h, None)})
        except Exception as e:
            entry["dns"] = f"<fail: {e}>"
        for scheme, port in (("https", 443), ("http", 80)):
            url = f"{scheme}://{h}/"
            try:
                req = urllib.request.Request(url, method="HEAD",
              headers={"User-Agent": "evidence-pack/1.0"})
                with urllib.request.urlopen(req, timeout=8) as r:
                    entry[scheme] = {"status": r.status, "server": r.headers.get("Server"),
 "date_hdr": r.headers.get("Date")}
            except urllib.error.HTTPError as e:
                entry[scheme] = {"status": e.code, "note": "http error (连通,服务返回错误)"}
            except Exception as e:
                entry[scheme] = {"error": type(e).__name__}
        out[h] = entry
    return out

def scan_install(root):
    root = pathlib.Path(root)
    files, binaries, redacted = [], [], []
    if not root.is_dir():
        return {"error": f"路径不存在: {root}"}
    for p in sorted(root.rglob("*")):
        if not p.is_file():
            continue
        rel = p.relative_to(root)
        try:
            h = hashlib.sha256(p.read_bytes()).hexdigest()
        except Exception:
            h = "unreadable"
        rec = {"path": str(rel), "size": p.stat().st_size,
               "mtime": time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(p.stat().st_mtime)),
               "sha256": h}
        if p.suffix.lower() in (".exe", ".dll", ".sys"):
            binaries.append(rec)
        files.append(rec)
        if p.suffix.lower() in LOG_EXTS and p.stat().st_size < 2_000_000:
            try:
                text = p.read_text(errors="replace")
                redacted.append({"path": str(rel),
 "content": SENSITIVE.sub(r"\1=<REDACTED>", text)})
            except Exception:
                pass
    return {"total_files": len(files), "binaries": binaries,
            "config_and_logs": redacted[:20]}

def collect_winevent(days=7):
    """Windows: 近 N天的应用/系统事件里带 error 的摘要"""
    return sh(["powershell", "-NoProfile", "-Command",
        f"Get-WinEvent -FilterHashtable @{{LogName='Application','StartTime=(Get-Date).AddDays({days})}} "
        "-ErrorAction SilentlyContinue | Where-Object LevelDisplayName -in 'Error','Warning' "
        "| Select-Object -First 60 TimeCreated,ProviderName,Id,Message "
        "| ConvertTo-Json -Depth 3"])

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--install", required=True)
    ap.add_argument("--hosts", nargs="*", default=[])
    ap.add_argument("--out", default="evidence.zip")
    args = ap.parse_args()

    pack = {
      "system": sys_info(),
     "network": net_check(args.hosts) if args.hosts else "未指定 --hosts,跳过",
   "install": scan_install(args.install),
    }
    if os.name == "nt":
        pack["windows_events"] = collect_winevent()

    # 时间脚本的输出如果之前跑过,一并带上
    tc = pathlib.Path("time_report.json")
    if tc.exists():
        pack["time_report"] = json.loads(tc.read_text())

    with zipfile.ZipFile(args.out, "w", zipfile.ZIP_DEFLATED) as z:
        z.writestr("report.json", json.dumps(pack, ensure_ascii=False, indent=2))
        for item in pack["install"].get("config_and_logs", []):
            z.writestr("logs/" + item["path"].replace("\\", "/"),
          item["content"].encode("utf-8"))
        for item in pack["install"].get("binaries", []):
            z.writestr("sha256sums.txt", f"{item['sha256']}  {item['path']}\n",
 zipfile.ZIP_CONST if False else None) if False else None
        sums = "\n".join(f"{b['sha256']}  {b['path']}"
